From 604d7fe775f334ecfe531955e66b05dbe3d85172 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:39:05 +0100
Subject: [PATCH] applets/taskmanager: show media controls only on the playing
 window

With grouping off, every window of a player's app got the media controls
and album art in its tooltip, as the window title check only ran for
group tooltips. Single tooltips now look at the app's other windows too.

BUG: 455654
---
 applets/taskmanager/qml/ToolTipDelegate.qml | 15 +++++++++++++++
 applets/taskmanager/qml/ToolTipInstance.qml |  6 +++---
 2 files changed, 18 insertions(+), 3 deletions(-)

diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..f195b02020 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -19,6 +19,7 @@ import org.kde.plasma.private.mpris as Mpris
 import org.kde.kirigami as Kirigami

 import org.kde.plasma.plasmoid
+import org.kde.taskmanager as TaskManager

 Loader {
     id: toolTipDelegate
@@ -82,6 +83,20 @@ Loader {
             virtualDesktops: toolTipDelegate.virtualDesktops
             activities: toolTipDelegate.activities
             model: null
+            hasTrackInATitle: {
+                const track = toolTipDelegate.playerData?.track;
+                if (!track) {
+                    return false;
+                }
+                for (let i = 0; i < tasksModel.count; ++i) {
+                    const index = tasksModel.makeModelIndex(i);
+                    if (tasksModel.data(index, TaskManager.AbstractTasksModel.AppPid) === toolTipDelegate.pidParent
+                            && (tasksModel.data(index, Qt.DisplayRole) ?? "").includes(track)) {
+                        return true;
+                    }
+                }
+                return false;
+            }
         }
     }

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..ff207510a6 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -372,7 +372,7 @@ ColumnLayout {
             // if this app is a browser, we also check the title, so album art is not shown when the user is on some other tab
             // in all other cases we can safely show the album art without checking the title
             readonly property bool available: (status === Image.Ready || status === Image.Loading)
-                && (!(toolTipDelegate.isGroup || backend.applicationCategories(launcherUrl).includes("WebBrowser")) || root.titleIncludesTrack)
+                && (!(toolTipDelegate.isGroup || root.hasTrackInATitle || backend.applicationCategories(launcherUrl).includes("WebBrowser")) || root.titleIncludesTrack)

             anchors.fill: parent
             // Indent by one pixel to make sure we never cover up the entire highlight
@@ -405,7 +405,7 @@ ColumnLayout {
         // when the instance is going to be destroyed
         active: (toolTipDelegate.parentTask?.tooltipControlsEnabled
              && toolTipDelegate.playerData
-             && ((root.hasTrackInATitle && albumArtImage.available) || (!root.hasTrackInATitle && root.index == 0))) ?? false
+             && ((root.hasTrackInATitle && root.titleIncludesTrack) || (!root.hasTrackInATitle && root.index == 0))) ?? false

         asynchronous: true
         visible: active
@@ -427,7 +427,7 @@ ColumnLayout {
              // Only load for one entry, as the controls only apply to one window.
              // If this is changed in the future, test for index != -1 to avoid loading
              // when the instance is going to be destroyed
-             && ((hasTrackInATitle && albumArtImage.available) || (!hasTrackInATitle && root.index == 0))
+             && ((root.hasTrackInATitle && root.titleIncludesTrack) || (!root.hasTrackInATitle && root.index == 0))
         asynchronous: true
         visible: active
         Layout.fillWidth: true
-- 
